94	     * 人工恢复：仅 PAUSED 可恢复为 ACTIVE；版本加一、开启新监控轮次、本轮统计清零。
95	     * 与取消并发时按行锁提交顺序决定唯一结果：取消先提交则恢复 409。
96	     */
97	    public ReleaseView resume(long releaseId, ResumeReleaseRequest request) {
98	        String fingerprint = String.join("|", "release.resume", String.valueOf(releaseId),
99	                String.valueOf(request.expectedVersion()), request.reason());
100	        return idempotency.execute(request.requestId(), "release.resume", fingerprint, () -> {
101	            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
