111	                .andExpect(jsonPath("$.roundSuccess").value(2));
112	
113	        // 样本 4：失败率 2/4 = 50%，恰好等于阈值，当次回执事务内原子暂停
114	        receipt(t4, "r-rc4", "FAILED");
115	        mockMvc.perform(get("/api/releases/" + releaseId + "/monitor"))
116	                .andExpect(jsonPath("$.status").value("PAUSED"))
117	                .andExpect(jsonPath("$.monitorRound").value(1))
