123	        // 暂停记录：轮次、触发任务、成功/失败数、UTC 时刻
124	        mockMvc.perform(get("/api/releases/" + releaseId + "/history"))
125	                .andExpect(jsonPath("$.pauses.length()").value(1))
126	                .andExpect(jsonPath("$.pauses[0].monitorRound").value(1))
127	                .andExpect(jsonPath("$.pauses[0].triggerTaskId").value(t4))
