129	                .andExpect(jsonPath("$.pauses[0].failedCount").value(2))
130	                .andExpect(jsonPath("$.pauses[0].pausedAtUtc").isString())
131	                .andExpect(jsonPath("$.resumes.length()").value(0));
132	        String pausedAt = com.jayway.jsonpath.JsonPath.read(
