138	    @Test
139	    void 重复回执不重复计数_取消任务不计样本() throws Exception {
140	        // floor=2, threshold=100：仅当 2/2 全失败才暂停
141	        long releaseId = createRelease("r-create", "m1", 100, 2, 100);
